# Round 2 edit of contract/primitives.json: replaces/adds the rows the critic rejected. Run: python3 build-rows-r2.py
# Evidence strings cite contract/measure-primitives.mjs ids; raw runs are in primitives-evidence/r2/<batch>/<id>/ (run.txt + primitives-measure.json).
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
P = os.path.join(HERE, '..', 'primitives.json')
d = json.load(open(P))
rows = d['rows']
by = {r['feature']: i for i, r in enumerate(rows)}

def find(prefix):
    for i, r in enumerate(rows):
        if r['feature'].startswith(prefix):
            return i
    raise KeyError(prefix)

RIGNOTE = ' Rig: REFEREE_REPO_ROOT=<shadow> SOLIDCRAFT_REFEREE_PKG=<pkg> bun contract/measure-primitives.mjs --only=<ids> (RIG.md); raw output under contract/primitives-evidence/r2/.'

def R(feature, status, evidence, sentence=None):
    r = {'feature': feature, 'status': status}
    if sentence:
        r['refusalSentence'] = sentence
    r['evidence'] = evidence
    return r

NOT_PLAIN = 'NOT A PLAIN SENTENCE (marked unsupported, not refused: the student does see text, but it carries an internal id such as box1 and a kernel command name such as solid.fillet, and it does not say what to change). '

new = {}
# rows folded into the replacement lists below
new['box option corner too large'] = []
new['ring with tube not thinner'] = []

